export function buildCases(input){const edit=fn=>{const d=structuredClone(input);fn(...d.body);return d;};const positives=[['original inline teaching assets',structuredClone(input)],['explicit disabled practice',edit((...nodes)=>nodes.forEach(n=>n.disabled=true))],['case-distinct accepted answers',edit((c,i,a)=>{i.answers=['blue','Blue'];a.answers=['tone','Tone'];})],['finite maximum answer lists',edit((c,i,a)=>{c.options=Array.from({length:8},(_,n)=>({...structuredClone(c.options[n%2]),id:'option'+n}));c.answerId='option7';i.answers=Array.from({length:12},(_,n)=>'answer'+n);a.answers=Array.from({length:12},(_,n)=>'sound'+n);})],['literal labels and transcripts',edit((c,i,a)=>{c.label='<script>literal title</script>';i.image.alt='<img src=untrusted>';a.audio.transcript='<svg onload=untrusted>';})],['explicit external media URLs',edit((c,i,a)=>{c.options[0].image.src='https://example.org/original-orange.png';i.image.src='https://example.org/original-blue.png';a.audio.src='https://example.org/original-tone.wav';})]];const sem=(name,fn,code,path)=>[name,edit(fn),code,path],s=(name,fn)=>[name,edit(fn),'SCHEMA'];const negatives=[sem('duplicate option ID',c=>c.options[1].id=c.options[0].id,'DUPLICATE_ID','/body/0/options/1/id'),sem('answer does not reference an option',c=>c.answerId='missing','LEARNING_ANSWER_REFERENCE','/body/0/answerId'),sem('blank accepted answer',(c,i)=>i.answers=['   '],'LEARNING_ANSWER_EMPTY','/body/1/answers/0'),sem('answers duplicate after trimming',(c,i)=>i.answers=['blue',' blue '],'DUPLICATE_ANSWER','/body/1/answers/1'),sem('SVG is not a raster media source',(c,i)=>i.image.src='data:image/svg+xml;base64,PHN2Zy8+','UNSAFE_URL','/body/1/image/src'),sem('unsafe option URL',c=>c.options[0].image.src='javascript:untrusted()','UNSAFE_URL','/body/0/options/0/image/src'),sem('blob audio source',(c,i,a)=>a.audio.src='blob:https://example.org/owned','UNSAFE_URL','/body/2/audio/src'),sem('empty audio payload',(c,i,a)=>a.audio.src='data:audio/wav;base64,','UNSAFE_URL','/body/2/audio/src'),sem('wildcard audio host',(c,i,a)=>a.audio.src='https://*.example.org/tone.wav','UNSAFE_URL','/body/2/audio/src'),sem('nonloopback IP audio host',(c,i,a)=>a.audio.src='https://192.0.2.1/tone.wav','UNSAFE_URL','/body/2/audio/src'),s('missing transcript',(c,i,a)=>delete a.audio.transcript),s('nonboolean disabled',c=>c.disabled='false'),s('speech recognition is not an input',(c,i,a)=>a.speechRecognition=true),s('choice requires two options',c=>c.options.pop()),s('answer overflow',(c,i)=>i.answers=Array.from({length:13},(_,n)=>'answer'+n)),s('answer text overflow',(c,i,a)=>a.answers=['a'.repeat(201)])];return{positives,negatives};}
